pub fn grammar_free_name_slot_binding() -> Symbol {
    thread_local! {
        static CACHED: Symbol = {
            "grammar_free_name_slot".to_string()
        };
    }
    CACHED.with(|c: &Symbol| c.clone())
}

pub fn grammar_lexeme_stamp_slot_binding() -> Symbol {
    thread_local! {
        static CACHED: Symbol = {
            "grammar_lexeme_stamp_slot".to_string()
        };
    }
    CACHED.with(|c: &Symbol| c.clone())
}

pub fn formal_binding_is_free_name_slot(binding: std::string::String) -> bool {
    (binding.clone() == "grammar_free_name_slot".to_string())
}

pub fn formal_binding_is_lexeme_stamp_slot(binding: std::string::String) -> bool {
    (binding.clone() == "grammar_lexeme_stamp_slot".to_string())
}

pub fn formal_binding_is_emitted_atom_from_slot(binding: std::string::String) -> bool {
    (formal_binding_is_free_name_slot(binding.clone()) || formal_binding_is_lexeme_stamp_slot(binding.clone()))
}

pub fn grammar_formal_terminal_free(identity: std::string::String) -> Rc<FormalGrammarSymbol> {
    grammar_formal_terminal_bound(identity, "grammar_free_name_slot".to_string())
}

pub fn grammar_formal_terminal_lexeme(identity: std::string::String) -> Rc<FormalGrammarSymbol> {
    grammar_formal_terminal_bound(identity, "grammar_lexeme_stamp_slot".to_string())
}

