pub fn formal_rhs_from_node(node: Rc<Node>) -> Rc<Witness<Rc<Vec<Rc<FormalGrammarSymbol>>>>> {
    match (*node.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => match (*node.children.clone().iter().cloned().fold(Rc::new(Witness::<Rc<Vec<_>>>::Holds {
    value: Rc::new(vec![]),
}), |acc: _, edge: Rc<Edge>| match (*acc.clone()).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Vec<_>>>::Violates {
    diagnostic: d.clone(),
}),
    Witness::Holds { value: symbols, .. } => match (*edge.label.clone()).clone() {
    EdgeLabel::Positional => match (*formal_grammar_symbol_from_node(edge.target.clone())).clone() {
    Witness::Holds { value: symbol, .. } => Rc::new(Witness::<Rc<Vec<Rc<FormalGrammarSymbol>>>>::Holds {
    value: crate::std_algebra::list_snoc_item(symbols.clone(), symbol.clone()),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Vec<_>>>::Violates {
    diagnostic: d.clone(),
}),
},
    EdgeLabel::Authored { name: _, .. } => acc.clone(),
    EdgeLabel::StructuralLabel { label: _, .. } => acc.clone(),
},
})).clone() {
    Witness::Holds { value: symbols, .. } => Rc::new(Witness::<Rc<Vec<_>>>::Holds {
    value: symbols.clone(),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Vec<_>>>::Violates {
    diagnostic: d.clone(),
}),
},
    Connective::Atom { identity: _, .. } => formal_rhs_from_node_otherwise(node.clone()),
    Connective::Disj => formal_rhs_from_node_otherwise(node.clone()),
    Connective::Arrow => formal_rhs_from_node_otherwise(node.clone()),
    Connective::Instantiation => formal_rhs_from_node_otherwise(node.clone()),
} },
    NodeKind::ComputationNode { behavior: _, .. } => formal_rhs_from_node_otherwise(node.clone()),
}
}

