pub fn grammar_relation_emitted_conj_slot_missing_diagnostic(emitted: Rc<Node>) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_conj_slot_missing".to_string(),
    at: crate::v2_std_diagnostic::node_locus(emitted),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
})
}

pub fn formal_conj_child_atom_head(rest: Rc<Vec<Rc<Node>>>, emitted: Rc<Node>) -> Rc<Witness<Rc<Node>>> {
    match crate::std_algebra::list_head(rest) {
    Some(slot_child) => match node_atom_identity_optional(slot_child.clone()) {
    Some(_) => Rc::new(Witness::<Rc<Node>>::Holds {
    value: slot_child.clone(),
}),
    std::option::Option::None => Rc::new(Witness::<Rc<Node>>::Violates {
    diagnostic: grammar_relation_emitted_conj_slot_missing_diagnostic(emitted.clone()),
}),
},
    std::option::Option::None => Rc::new(Witness::<Rc<Node>>::Violates {
    diagnostic: grammar_relation_emitted_conj_slot_missing_diagnostic(emitted.clone()),
}),
}
}

pub fn grammar_cursor_rest<T: Clone>(xs: Rc<Vec<T>>) -> Rc<Vec<T>> {
    crate::std_algebra::skip(xs, 1)
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum EmittedRhsMatchState {
    EmittedRhsMatchOk {
        index: i64,
        children_rest: Rc<Vec<Rc<Node>>>,
        slots_rest: Rc<Vec<Rc<EmittedProductionResolution>>>,
    },
    EmittedRhsMatchFail,
}
impl EmittedRhsMatchState {
    pub fn index(&self) -> i64 {
        match self {
            EmittedRhsMatchState::EmittedRhsMatchOk { index: __val, .. } => __val.clone(),
            EmittedRhsMatchState::EmittedRhsMatchFail => panic!("no index on unit variant"),
        }
    }
    pub fn children_rest(&self) -> Rc<Vec<Rc<Node>>> {
        match self {
            EmittedRhsMatchState::EmittedRhsMatchOk { children_rest: __val, .. } => __val.clone(),
            EmittedRhsMatchState::EmittedRhsMatchFail => panic!("no children_rest on unit variant"),
        }
    }
    pub fn slots_rest(&self) -> Rc<Vec<Rc<EmittedProductionResolution>>> {
        match self {
            EmittedRhsMatchState::EmittedRhsMatchOk { slots_rest: __val, .. } => __val.clone(),
            EmittedRhsMatchState::EmittedRhsMatchFail => panic!("no slots_rest on unit variant"),
        }
    }
}

pub fn emitted_rhs_match_advanced(index: i64, children_rest: Rc<Vec<Rc<Node>>>, slots_rest: Rc<Vec<Rc<EmittedProductionResolution>>>) -> Rc<EmittedRhsMatchState> {
    Rc::new(EmittedRhsMatchState::EmittedRhsMatchOk {
    index: v1_rt::int_add(index.clone(), 1),
    children_rest: grammar_cursor_rest(children_rest),
    slots_rest: grammar_cursor_rest(slots_rest),
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct EmittedProductionResolution {
    pub emitted: Rc<Node>,
    pub matched: Rc<Vec<Rc<FormalProduction>>>,
    pub slots: Rc<Vec<Rc<EmittedProductionResolution>>>,
}

pub fn formal_production_rhs_matches_nonterminal_step(index: i64, children_rest: Rc<Vec<Rc<Node>>>, slots_rest: Rc<Vec<Rc<EmittedProductionResolution>>>, nonterminal: Rc<FormalNonterminal>) -> Rc<EmittedRhsMatchState> {
    match crate::std_algebra::list_head(slots_rest.clone()) {
    Some(slot) => match (*resolution_production_for_lhs_exact(slot.clone(), nonterminal.identity.clone())).clone() {
    Witness::Holds { value: _, .. } => emitted_rhs_match_advanced(index, children_rest, slots_rest.clone()),
    Witness::Violates { diagnostic: _, .. } => Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail),
},
    std::option::Option::None => Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail),
}
}

pub fn formal_production_rhs_matches_emitted_conj_step(state: Rc<EmittedRhsMatchState>, resolution: Rc<EmittedProductionResolution>, children: Rc<Vec<Rc<Node>>>, symbol: Rc<FormalGrammarSymbol>) -> Rc<EmittedRhsMatchState> {
    match (*state.clone()).clone() {
    EmittedRhsMatchState::EmittedRhsMatchFail => state.clone(),
    EmittedRhsMatchState::EmittedRhsMatchOk { index, children_rest, slots_rest, .. } => match (*symbol.clone()).clone() {
    FormalGrammarSymbol::FormalNestedNonterminalOccurrence { nonterminal, .. } => formal_production_rhs_matches_nonterminal_step(index.clone(), children_rest.clone(), slots_rest.clone(), nonterminal.clone()),
    FormalGrammarSymbol::FormalTerminalOccurrence { terminal, binding, .. } => match binding.clone() {
    Some(binding_symbol) => match formal_binding_conj_slot_arm(binding_symbol.clone()) {
    FormalBindingConjSlotArm::FormalBindingConjSlotEmittedAtom => match (*formal_conj_child_atom_head(children_rest.clone(), resolution.emitted.clone())).clone() {
    Witness::Holds { value: _, .. } => emitted_rhs_match_advanced(index.clone(), children_rest.clone(), slots_rest.clone()),
    Witness::Violates { diagnostic: _, .. } => Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail),
},
    FormalBindingConjSlotArm::FormalBindingConjSlotExactBinding => match (*formal_conj_child_atom_head(children_rest.clone(), resolution.emitted.clone())).clone() {
    Witness::Holds { value: slot_child, .. } => match node_atom_identity_optional(slot_child.clone()) {
    Some(atom_id) => if (atom_id.clone() == binding_symbol.clone()) {
        emitted_rhs_match_advanced(index.clone(), children_rest.clone(), slots_rest.clone())
    } else {
        Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail)
    },
    std::option::Option::None => Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail),
},
    Witness::Violates { diagnostic: _, .. } => Rc::new(EmittedRhsMatchState::EmittedRhsMatchFail),
},
},
    std::option::Option::None => state.clone(),
},
    FormalGrammarSymbol::FormalNonterminalOccurrence { nonterminal: nonterminal, .. } => formal_production_rhs_matches_nonterminal_step(index.clone(), children_rest.clone(), slots_rest.clone(), nonterminal.clone()),
},
}
}

pub fn formal_production_rhs_matches_emitted_conj(production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>, children: Rc<Vec<Rc<Node>>>, child_count: i64) -> bool {
    match (*resolution.emitted.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => formal_production_rhs_matches_emitted_conj_conj(production, resolution.clone(), children, child_count),
    Connective::Atom { identity: _, .. } => false,
    Connective::Disj => false,
    Connective::Arrow => false,
    Connective::Instantiation => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

pub fn formal_production_rhs_matches_emitted_conj_conj(production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>, children: Rc<Vec<Rc<Node>>>, child_count: i64) -> bool {
    match (*crate::std_algebra::fold_list(production.rhs.clone(), Rc::new(EmittedRhsMatchState::EmittedRhsMatchOk {
    index: 0,
    children_rest: children.clone(),
    slots_rest: resolution.slots.clone(),
}), |state, symbol| formal_production_rhs_matches_emitted_conj_step(state, resolution.clone(), children.clone(), symbol))).clone() {
    EmittedRhsMatchState::EmittedRhsMatchOk { index, .. } => (index.clone() == child_count.clone()),
    EmittedRhsMatchState::EmittedRhsMatchFail => false,
}
}

pub fn formal_production_matches_resolution(production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>, children: Rc<Vec<Rc<Node>>>, child_count: i64) -> bool {
    match (*resolution.emitted.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: atom_id, .. } => match formal_production_rhs_singleton_terminal_identity(production.clone()) {
    Some(terminal_id) => (atom_id.clone() == terminal_id.clone()),
    std::option::Option::None => match formal_production_rhs_singleton_binding(production.clone()) {
    Some(binding) => match formal_binding_conj_slot_arm(binding.clone()) {
    FormalBindingConjSlotArm::FormalBindingConjSlotEmittedAtom => true,
    FormalBindingConjSlotArm::FormalBindingConjSlotExactBinding => (atom_id.clone() == binding.clone()),
},
    std::option::Option::None => false,
},
},
    Connective::Conj => formal_production_rhs_matches_emitted_conj(production.clone(), resolution.clone(), children, child_count),
    Connective::Disj => false,
    Connective::Arrow => false,
    Connective::Instantiation => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

pub fn emitted_shape_supported_for_lhs_exact(child: Rc<Node>) -> bool {
    match (*child.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => true,
    Connective::Atom { identity: _, .. } => true,
    Connective::Disj => false,
    Connective::Arrow => false,
    Connective::Instantiation => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

pub fn formal_symbol_list_contains(xs: Rc<Vec<Symbol>>, wanted: std::string::String) -> bool {
    crate::std_algebra::fold_list(xs, false, |acc, x| (acc.clone() || (x.clone() == wanted.clone())))
}

pub fn formal_symbol_list_insert(xs: Rc<Vec<Symbol>>, item: std::string::String) -> Rc<Vec<Symbol>> {
    if formal_symbol_list_contains(xs.clone(), item.clone()) {
        xs.clone()
    } else {
        crate::std_algebra::list_snoc_item(xs.clone(), item.clone())
    }
}

pub fn formal_production_slot_nonterminals(production: Rc<FormalProduction>) -> Rc<Vec<Option<std::string::String>>> {
    crate::std_algebra::fold_list(production.rhs.clone(), Rc::new(vec![]), |acc, symbol| match (*symbol.clone()).clone() {
    FormalGrammarSymbol::FormalTerminalOccurrence { binding, .. } => match binding.clone() {
    Some(_) => crate::std_algebra::list_snoc_item(acc.clone(), crate::std_optional::optional_absent()),
    std::option::Option::None => acc.clone(),
},
    FormalGrammarSymbol::FormalNonterminalOccurrence { nonterminal: nonterminal, .. } => crate::std_algebra::list_snoc_item(acc.clone(), crate::std_optional::optional_present(nonterminal.identity.clone())),
    FormalGrammarSymbol::FormalNestedNonterminalOccurrence { nonterminal, .. } => crate::std_algebra::list_snoc_item(acc.clone(), crate::std_optional::optional_present(nonterminal.identity.clone())),
})
}

pub fn formal_slot_cursor_heads_asked(cursors: Rc<Vec<Rc<Vec<Option<std::string::String>>>>>) -> Rc<Vec<Symbol>> {
    crate::std_algebra::fold_list(cursors, Rc::new(vec![]), |acc, cursor| match crate::std_algebra::list_head(cursor) {
    Some(Some(nonterminal)) => formal_symbol_list_insert(acc, nonterminal.clone()),
    Some(std::option::Option::None) => acc.clone(),
    std::option::Option::None => acc.clone(),
})
}

pub fn formal_slot_cursors_advanced(cursors: Rc<Vec<Rc<Vec<Option<std::string::String>>>>>) -> Rc<Vec<Rc<Vec<Option<std::string::String>>>>> {
    crate::std_algebra::fold_list(cursors, Rc::new(vec![]), |acc, cursor| crate::std_algebra::list_snoc_item(acc, grammar_cursor_rest(cursor)))
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct SlotResolutionScan {
    pub cursors: Rc<Vec<Rc<Vec<Option<std::string::String>>>>>,
    pub slots: Rc<Vec<Rc<EmittedProductionResolution>>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct FormalLhsBuckets {
    pub untagged: Rc<Vec<Rc<FormalProduction>>>,
    pub tagged: Rc<HashMap<Symbol, Rc<Vec<Rc<FormalProduction>>>>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct FormalProductionIndex {
    pub by_lhs: Rc<HashMap<Symbol, Rc<FormalLhsBuckets>>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum FormalLeadingTag {
    FormalLeadingExactBinding {
        binding: Symbol,
    },
    FormalNoLeadingTag,
}
impl FormalLeadingTag {
    pub fn binding(&self) -> Symbol {
        match self {
            FormalLeadingTag::FormalLeadingExactBinding { binding: __val, .. } => __val.clone(),
            FormalLeadingTag::FormalNoLeadingTag => panic!("no binding on unit variant"),
        }
    }
}

pub fn formal_production_leading_tag(production: Rc<FormalProduction>) -> Rc<FormalLeadingTag> {
    { let __fm = production.rhs.clone(); if __fm.is_empty() { Rc::new(FormalLeadingTag::FormalNoLeadingTag) } else { let first = (*__fm)[0].clone(); formal_symbol_leading_tag(first.clone()) } }
}

pub fn formal_symbol_leading_tag(symbol: Rc<FormalGrammarSymbol>) -> Rc<FormalLeadingTag> {
    match (*symbol.clone()).clone() {
    FormalGrammarSymbol::FormalTerminalOccurrence { binding, .. } => match binding.clone() {
    Some(b) => match formal_binding_conj_slot_arm(b.clone()) {
    FormalBindingConjSlotArm::FormalBindingConjSlotExactBinding => Rc::new(FormalLeadingTag::FormalLeadingExactBinding {
    binding: b.clone(),
}),
    FormalBindingConjSlotArm::FormalBindingConjSlotEmittedAtom => Rc::new(FormalLeadingTag::FormalNoLeadingTag),
},
    std::option::Option::None => Rc::new(FormalLeadingTag::FormalNoLeadingTag),
},
    FormalGrammarSymbol::FormalNonterminalOccurrence { nonterminal: _, .. } => Rc::new(FormalLeadingTag::FormalNoLeadingTag),
    FormalGrammarSymbol::FormalNestedNonterminalOccurrence { .. } => Rc::new(FormalLeadingTag::FormalNoLeadingTag),
}
}

pub fn formal_lhs_buckets_add(buckets: Rc<FormalLhsBuckets>, production: Rc<FormalProduction>) -> Rc<FormalLhsBuckets> {
    match (*formal_production_leading_tag(production.clone())).clone() {
    FormalLeadingTag::FormalNoLeadingTag => Rc::new(FormalLhsBuckets {
    untagged: crate::std_algebra::list_snoc_item(buckets.untagged.clone(), production.clone()),
    tagged: buckets.tagged.clone(),
}),
    FormalLeadingTag::FormalLeadingExactBinding { binding: b, .. } => {
        let prior = match v1_rt::lookup(&buckets.tagged.clone(), b.clone()) {
    Some(xs) => xs.clone(),
    std::option::Option::None => Rc::new(vec![]),
};
Rc::new(FormalLhsBuckets {
    untagged: buckets.untagged.clone(),
    tagged: v1_rt::rc_map_insert(buckets.tagged.clone(), b.clone(), crate::std_algebra::list_snoc_item(prior, production.clone())),
})
},
}
}

pub fn formal_production_index(productions: Rc<Vec<Rc<FormalProduction>>>) -> Rc<FormalProductionIndex> {
    Rc::new(FormalProductionIndex {
    by_lhs: crate::std_algebra::fold_list(productions, v1_rt::rc_empty_map::<_, _>(), |acc, production| {
        let prior = match v1_rt::lookup(&acc, production.lhs.identity.clone()) {
    Some(b) => b.clone(),
    std::option::Option::None => Rc::new(FormalLhsBuckets {
    untagged: Rc::new(vec![]),
    tagged: v1_rt::rc_empty_map::<_, _>(),
}),
};
v1_rt::rc_map_insert(acc.clone(), production.lhs.identity.clone(), formal_lhs_buckets_add(prior.clone(), production.clone()))
}),
})
}

pub fn formal_emitted_index_key(emitted: Rc<Node>, children: Rc<Vec<Rc<Node>>>) -> Option<std::string::String> {
    match (*emitted.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => crate::std_optional::optional_present(id.clone()),
    Connective::Conj => { let __fm = children.clone(); if __fm.is_empty() { crate::std_optional::optional_absent() } else { let first = (*__fm)[0].clone(); node_atom_identity_optional(first.clone()) } },
    Connective::Disj => crate::std_optional::optional_absent(),
    Connective::Arrow => crate::std_optional::optional_absent(),
    Connective::Instantiation => crate::std_optional::optional_absent(),
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn formal_productions_asked_indexed(index: Rc<FormalProductionIndex>, asked: Rc<Vec<Symbol>>, emitted: Rc<Node>, children: Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<FormalProduction>>> {
    {
        let tag = formal_emitted_index_key(emitted, children);
crate::std_algebra::fold_list(asked, Rc::new(vec![]), |acc, lhs| match v1_rt::lookup(&index.by_lhs.clone(), lhs) {
    Some(buckets) => {
            let with_untagged = crate::std_algebra::list_append(acc, buckets.untagged.clone());
match tag.clone() {
    Some(t) => match v1_rt::lookup(&buckets.tagged.clone(), t.clone()) {
    Some(entries) => crate::std_algebra::list_append(with_untagged.clone(), entries.clone()),
    std::option::Option::None => with_untagged.clone(),
},
    std::option::Option::None => with_untagged.clone(),
}
},
    std::option::Option::None => acc.clone(),
})
}
}

pub fn resolve_emitted_productions_slots(index: Rc<FormalProductionIndex>, candidates: Rc<Vec<Rc<FormalProduction>>>, children: Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<EmittedProductionResolution>>> {
    {
        let scan = crate::std_algebra::fold_list(children, Rc::new(SlotResolutionScan {
    cursors: crate::std_algebra::fold_list(candidates, Rc::new(vec![]), |acc, candidate| crate::std_algebra::list_snoc_item(acc, formal_production_slot_nonterminals(candidate))),
    slots: Rc::new(vec![]),
}), |acc, child| Rc::new(SlotResolutionScan {
    cursors: formal_slot_cursors_advanced(acc.cursors.clone()),
    slots: crate::std_algebra::list_snoc_item(acc.slots.clone(), resolve_emitted_productions_asked_in(index.clone(), formal_slot_cursor_heads_asked(acc.cursors.clone()), child)),
}));
scan.slots.clone()
}
}

pub fn resolve_emitted_productions_matched_step(acc: Rc<Vec<Rc<FormalProduction>>>, production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>, children: Rc<Vec<Rc<Node>>>, child_count: i64) -> Rc<Vec<Rc<FormalProduction>>> {
    if formal_production_matches_resolution(production.clone(), resolution, children, child_count) {
        crate::std_algebra::list_snoc_item(acc, production.clone())
    } else {
        acc.clone()
    }
}

pub fn resolve_emitted_productions_asked(productions: Rc<Vec<Rc<FormalProduction>>>, asked: Rc<Vec<Symbol>>, emitted: Rc<Node>) -> Rc<EmittedProductionResolution> {
    resolve_emitted_productions_asked_in(formal_production_index(productions), asked, emitted)
}

pub fn resolve_emitted_productions_asked_in(index: Rc<FormalProductionIndex>, asked: Rc<Vec<Symbol>>, emitted: Rc<Node>) -> Rc<EmittedProductionResolution> {
    {
        let children = conj_positional_children(emitted.clone());
let candidates = formal_productions_asked_indexed(index.clone(), asked, emitted.clone(), children.clone());
let child_count = conj_positional_child_count(children.clone());
let unmatched = Rc::new(EmittedProductionResolution {
    emitted: emitted.clone(),
    matched: Rc::new(vec![]),
    slots: resolve_emitted_productions_slots(index.clone(), candidates.clone(), children.clone()),
});
Rc::new(EmittedProductionResolution {
    emitted: emitted.clone(),
    matched: crate::std_algebra::fold_list(candidates.clone(), Rc::new(vec![]), |acc, production| resolve_emitted_productions_matched_step(acc, production, unmatched.clone(), children.clone(), child_count.clone())),
    slots: unmatched.slots.clone(),
})
}
}

pub fn formal_productions_all_lhs(productions: Rc<Vec<Rc<FormalProduction>>>) -> Rc<Vec<Symbol>> {
    crate::std_algebra::fold_list(productions, Rc::new(vec![]), |acc, production| formal_symbol_list_insert(acc, production.lhs.identity.clone()))
}

pub fn resolve_emitted_productions(productions: Rc<Vec<Rc<FormalProduction>>>, emitted: Rc<Node>) -> Rc<EmittedProductionResolution> {
    resolve_emitted_productions_asked(productions.clone(), formal_productions_all_lhs(productions.clone()), emitted)
}

pub fn lhs_exact_production_match_fold_step(acc: Rc<LhsExactProductionMatchFold>, resolution: Rc<EmittedProductionResolution>, lhs: std::string::String, candidate: Rc<FormalProduction>) -> Rc<LhsExactProductionMatchFold> {
    if formal_production_matches_lhs_and_slot_count(candidate.clone(), lhs, emitted_node_slot_count(resolution.emitted.clone())) {
        match (*acc.clone()).clone() {
    LhsExactProductionMatchFold::LhsExactProductionMatchNone => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchOne {
    production: candidate.clone(),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchOne { production: _, .. } => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchMany),
    LhsExactProductionMatchFold::LhsExactProductionMatchMany => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchMany),
}
    } else {
        acc.clone()
    }
}

pub fn resolution_production_for_lhs_exact(resolution: Rc<EmittedProductionResolution>, lhs: std::string::String) -> Rc<Witness<Rc<FormalProduction>>> {
    if emitted_shape_supported_for_lhs_exact(resolution.emitted.clone()) {
        match (*crate::std_algebra::fold_list(resolution.matched.clone(), Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchNone), |acc, candidate| lhs_exact_production_match_fold_step(acc, resolution.clone(), lhs.clone(), candidate))).clone() {
    LhsExactProductionMatchFold::LhsExactProductionMatchNone => Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_production_not_found".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchMany => Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_row_backward_selection_ambiguous".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchOne { production: production, .. } => Rc::new(Witness::<Rc<FormalProduction>>::Holds {
    value: production.clone(),
}),
}
    } else {
        Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_not_conj".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
})
    }
}

pub fn resolution_unique_emitted_match(resolution: Rc<EmittedProductionResolution>) -> Rc<Witness<Rc<FormalProduction>>> {
    if emitted_shape_supported_for_lhs_exact(resolution.emitted.clone()) {
        match (*crate::std_algebra::fold_list(resolution.matched.clone(), Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchNone), |acc, candidate| match (*acc.clone()).clone() {
    LhsExactProductionMatchFold::LhsExactProductionMatchNone => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchOne {
    production: candidate.clone(),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchOne { production: _, .. } => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchMany),
    LhsExactProductionMatchFold::LhsExactProductionMatchMany => Rc::new(LhsExactProductionMatchFold::LhsExactProductionMatchMany),
})).clone() {
    LhsExactProductionMatchFold::LhsExactProductionMatchNone => Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_production_not_found".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchMany => Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_row_backward_selection_ambiguous".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
}),
    LhsExactProductionMatchFold::LhsExactProductionMatchOne { production: production, .. } => Rc::new(Witness::<Rc<FormalProduction>>::Holds {
    value: production.clone(),
}),
}
    } else {
        Rc::new(Witness::<Rc<FormalProduction>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_not_conj".to_string(),
    at: crate::v2_std_diagnostic::node_locus(resolution.emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
})
    }
}

pub fn formal_production_matches_lhs_exact_child(productions: Rc<Vec<Rc<FormalProduction>>>, lhs: std::string::String, child: Rc<Node>, candidate: Rc<FormalProduction>) -> bool {
    if emitted_shape_supported_for_lhs_exact(child.clone()) {
        {
            let resolution = resolve_emitted_productions_asked(productions, Rc::new(vec![lhs.clone()]), child.clone());
let children = conj_positional_children(child.clone());
(formal_production_matches_lhs_and_slot_count(candidate.clone(), lhs.clone(), emitted_node_slot_count(child.clone())) && formal_production_matches_resolution(candidate.clone(), resolution, children.clone(), conj_positional_child_count(children.clone())))
}
    } else {
        false
    }
}

pub fn formal_production_for_lhs_exact(productions: Rc<Vec<Rc<FormalProduction>>>, lhs: std::string::String, child: Rc<Node>) -> Rc<Witness<Rc<FormalProduction>>> {
    resolution_production_for_lhs_exact(resolve_emitted_productions_asked(productions, Rc::new(vec![lhs.clone()]), child), lhs.clone())
}

pub fn derive_grammar_relation_row_for_lhs(productions: Rc<Vec<Rc<FormalProduction>>>, lhs: std::string::String, emitted: Rc<Node>) -> Rc<Witness<Rc<Node>>> {
    {
        let resolution = resolve_emitted_productions_asked(productions, Rc::new(vec![lhs.clone()]), emitted);
match (*resolution_production_for_lhs_exact(resolution.clone(), lhs.clone())).clone() {
    Witness::Holds { value: production, .. } => derive_grammar_relation_row_node_resolved(production.clone(), resolution.clone()),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Node>>::Violates {
    diagnostic: d.clone(),
}),
}
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct DeriveGrammarRelationTokensProgress {
    pub edges: Rc<Vec<Rc<Edge>>>,
    pub conj_index: i64,
    pub conj_children: Rc<Vec<Rc<Node>>>,
    pub children_rest: Rc<Vec<Rc<Node>>>,
    pub slots_rest: Rc<Vec<Rc<EmittedProductionResolution>>>,
}

pub fn emitted_node_slot_count(emitted: Rc<Node>) -> i64 {
    match (*emitted.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => conj_positional_child_count(conj_positional_children(emitted.clone())),
    Connective::Atom { identity: _, .. } => 0,
    Connective::Disj => v1_rt::int_sub(0, 1),
    Connective::Arrow => v1_rt::int_sub(0, 1),
    Connective::Instantiation => v1_rt::int_sub(0, 1),
} },
    NodeKind::ComputationNode { behavior: _, .. } => v1_rt::int_sub(0, 1),
}
}

pub fn derive_grammar_relation_nonterminal_step(edges: Rc<Vec<Rc<Edge>>>, conj_index: i64, conj_children: Rc<Vec<Rc<Node>>>, children_rest: Rc<Vec<Rc<Node>>>, slots_rest: Rc<Vec<Rc<EmittedProductionResolution>>>, emitted: Rc<Node>, nonterminal: Rc<FormalNonterminal>) -> Rc<Witness<Rc<DeriveGrammarRelationTokensProgress>>> {
    match crate::std_algebra::list_head(slots_rest.clone()) {
    Some(slot) => match (*resolution_production_for_lhs_exact(slot.clone(), nonterminal.identity.clone())).clone() {
    Witness::Holds { value: nested, .. } => match (*derive_grammar_relation_token_edges_resolved(nested.clone(), slot.clone())).clone() {
    Witness::Holds { value: nested_edges, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: crate::std_algebra::list_append(edges, nested_edges.clone()),
    conj_index: v1_rt::int_add(conj_index.clone(), 1),
    conj_children: conj_children.clone(),
    children_rest: grammar_cursor_rest(children_rest),
    slots_rest: grammar_cursor_rest(slots_rest.clone()),
}),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: d.clone(),
}),
},
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: d.clone(),
}),
},
    std::option::Option::None => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_conj_slot_missing".to_string(),
    at: crate::v2_std_diagnostic::node_locus(emitted),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
}),
}
}

pub fn derive_grammar_relation_token_edges_recursive_step(progress: Rc<Witness<Rc<DeriveGrammarRelationTokensProgress>>>, resolution: Rc<EmittedProductionResolution>, emitted: Rc<Node>, symbol: Rc<FormalGrammarSymbol>) -> Rc<Witness<Rc<DeriveGrammarRelationTokensProgress>>> {
    match (*progress.clone()).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: d.clone(),
}),
    Witness::Holds { value: ref __rc_value, .. } => { match __rc_value.as_ref() {
    DeriveGrammarRelationTokensProgress { edges, conj_index, conj_children, children_rest, slots_rest, .. } => match (*symbol.clone()).clone() {
    FormalGrammarSymbol::FormalNestedNonterminalOccurrence { nonterminal, unit, .. } => match (*derive_grammar_relation_nonterminal_step(Rc::new(vec![]), conj_index.clone(), conj_children.clone(), children_rest.clone(), slots_rest.clone(), emitted.clone(), nonterminal.clone())).clone() {
    Witness::Holds { value: inner, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: crate::std_algebra::list_snoc_item(edges.clone(), grammar_nested_block_edge(unit.clone(), inner.edges.clone())),
    conj_index: inner.conj_index.clone(),
    conj_children: conj_children.clone(),
    children_rest: inner.children_rest.clone(),
    slots_rest: inner.slots_rest.clone(),
}),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: d.clone(),
}),
},
    FormalGrammarSymbol::FormalTerminalOccurrence { terminal, binding, .. } => match binding.clone() {
    Some(binding_symbol) => match formal_binding_conj_slot_arm(binding_symbol.clone()) {
    FormalBindingConjSlotArm::FormalBindingConjSlotEmittedAtom => match (*formal_conj_child_atom_head(children_rest.clone(), emitted.clone())).clone() {
    Witness::Holds { value: slot_child, .. } => match node_atom_identity_optional(slot_child.clone()) {
    Some(atom_id) => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: crate::std_algebra::list_snoc_item(edges.clone(), grammar_terminal_occurrence_to_token_edge(terminal.clone(), crate::std_optional::optional_present(atom_id.clone()))),
    conj_index: v1_rt::int_add(conj_index.clone(), 1),
    conj_children: conj_children.clone(),
    children_rest: grammar_cursor_rest(children_rest.clone()),
    slots_rest: grammar_cursor_rest(slots_rest.clone()),
}),
}),
    std::option::Option::None => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: grammar_relation_emitted_conj_slot_missing_diagnostic(emitted.clone()),
}),
},
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Violates {
    diagnostic: d.clone(),
}),
},
    FormalBindingConjSlotArm::FormalBindingConjSlotExactBinding => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: crate::std_algebra::list_snoc_item(edges.clone(), grammar_terminal_occurrence_to_token_edge(terminal.clone(), binding.clone())),
    conj_index: v1_rt::int_add(conj_index.clone(), 1),
    conj_children: conj_children.clone(),
    children_rest: grammar_cursor_rest(children_rest.clone()),
    slots_rest: grammar_cursor_rest(slots_rest.clone()),
}),
}),
},
    std::option::Option::None => Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: crate::std_algebra::list_snoc_item(edges.clone(), grammar_terminal_occurrence_to_token_edge(terminal.clone(), binding.clone())),
    conj_index: conj_index.clone(),
    conj_children: conj_children.clone(),
    children_rest: children_rest.clone(),
    slots_rest: slots_rest.clone(),
}),
}),
},
    FormalGrammarSymbol::FormalNonterminalOccurrence { nonterminal: nonterminal, .. } => derive_grammar_relation_nonterminal_step(edges.clone(), conj_index.clone(), conj_children.clone(), children_rest.clone(), slots_rest.clone(), emitted.clone(), nonterminal.clone()),
},
} },
}
}

pub fn derive_grammar_relation_token_edges_resolved(production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>) -> Rc<Witness<Rc<Vec<Rc<Edge>>>>> {
    {
        let emitted = resolution.emitted.clone();
let conj_children = conj_positional_children(emitted.clone());
match (*crate::std_algebra::fold_list(production.rhs.clone(), Rc::new(Witness::<Rc<DeriveGrammarRelationTokensProgress>>::Holds {
    value: Rc::new(DeriveGrammarRelationTokensProgress {
    edges: Rc::new(vec![]),
    conj_index: 0,
    conj_children: conj_children.clone(),
    children_rest: conj_children.clone(),
    slots_rest: resolution.slots.clone(),
}),
}), |progress, symbol| derive_grammar_relation_token_edges_recursive_step(progress, resolution.clone(), emitted.clone(), symbol))).clone() {
    Witness::Holds { value: ref __rc_value, .. } => { match __rc_value.as_ref() {
    DeriveGrammarRelationTokensProgress { edges: result, conj_index, conj_children: walked_conj_children, .. } => if (conj_index.clone() == conj_positional_child_count(walked_conj_children.clone())) {
            Rc::new(Witness::<Rc<Vec<_>>>::Holds {
    value: result.clone(),
})
        } else {
            Rc::new(Witness::<Rc<Vec<_>>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_conj_slot_surplus".to_string(),
    at: crate::v2_std_diagnostic::node_locus(emitted.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
})
        },
} },
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Vec<_>>>::Violates {
    diagnostic: d.clone(),
}),
}
}
}

pub fn grammar_relation_token_edge_targets(edges: Rc<Vec<Rc<Edge>>>) -> Rc<Vec<Rc<Node>>> {
    edges.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<Node>>>, e: Rc<Edge>| crate::std_algebra::list_snoc_item(acc, e.target.clone()))
}

pub fn derive_grammar_relation_row_node(production: Rc<FormalProduction>, productions: Rc<Vec<Rc<FormalProduction>>>, emitted: Rc<Node>) -> Rc<Witness<Rc<Node>>> {
    derive_grammar_relation_row_node_resolved(production.clone(), resolve_emitted_productions_asked(productions, Rc::new(vec![production.lhs.identity.clone()]), emitted))
}

pub fn derive_grammar_relation_row_node_resolved(production: Rc<FormalProduction>, resolution: Rc<EmittedProductionResolution>) -> Rc<Witness<Rc<Node>>> {
    {
        let emitted = resolution.emitted.clone();
match (*emitted.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => match (*derive_grammar_relation_token_edges_resolved(production.clone(), resolution.clone())).clone() {
    Witness::Holds { value: token_edges, .. } => Rc::new(Witness::<Rc<Node>>::Holds {
    value: grammar_relation_row_to_node(derive_grammar_relation_row(production.clone(), emitted.clone()), grammar_relation_tokens_node(grammar_relation_token_edge_targets(token_edges.clone()), |token_node| token_node.clone())),
}),
    Witness::Violates { diagnostic: d, .. } => Rc::new(Witness::<Rc<Node>>::Violates {
    diagnostic: d.clone(),
}),
},
    Connective::Atom { identity: _, .. } => derive_grammar_relation_row_node_resolved_otherwise(emitted.clone()),
    Connective::Disj => derive_grammar_relation_row_node_resolved_otherwise(emitted.clone()),
    Connective::Arrow => derive_grammar_relation_row_node_resolved_otherwise(emitted.clone()),
    Connective::Instantiation => derive_grammar_relation_row_node_resolved_otherwise(emitted.clone()),
} },
    NodeKind::ComputationNode { behavior: _, .. } => derive_grammar_relation_row_node_resolved_otherwise(emitted.clone()),
}
}
}

pub fn derive_grammar_relation_row_node_resolved_otherwise(emitted: Rc<Node>) -> Rc<Witness<Rc<Node>>> {
    Rc::new(Witness::<Rc<Node>>::Violates {
    diagnostic: Rc::new(Diagnostic {
    reason: "grammar_relation_emitted_not_conj".to_string(),
    at: crate::v2_std_diagnostic::node_locus(emitted),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
}),
})
}

pub fn grammar_expr_node(children: Rc<Vec<Rc<Edge>>>) -> Rc<Node> {
    Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}),
    children: children.clone(),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}

pub fn grammar_expr_to_node(expr: Rc<GrammarExpr>) -> Rc<Node> {
    fold_grammar_expr(expr, Rc::new(GrammarExprFold {
    terminal: { Rc::new(move |token_class, stamp| match (*stamp.clone()).clone() {
    TerminalStampMode::StampBinding { binding: b, .. } => grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_terminal_token_class_node_projection".to_string(), grammar_atom(token_class.clone())), grammar_named_edge("grammar_terminal_binding_node_projection".to_string(), grammar_atom(b.clone()))])),
    TerminalStampMode::StampClass => grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_terminal_token_class_node_projection".to_string(), grammar_atom(token_class.clone()))])),
    TerminalStampMode::StampLexeme => grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_terminal_token_class_node_projection".to_string(), grammar_atom(token_class.clone())), grammar_named_edge("grammar_terminal_stamp_lexeme_node_projection".to_string(), grammar_atom("grammar_terminal_stamp_lexeme".to_string()))])),
}) },
    literal_terminal: { Rc::new(move |token_class, lexeme| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_terminal_token_class_node_projection".to_string(), grammar_atom(token_class.clone())), grammar_named_edge("grammar_terminal_literal_lexeme_node_projection".to_string(), grammar_atom(lexeme.clone()))]))) },
    nonterminal: { Rc::new(move |production| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_nonterminal_production_node_projection".to_string(), grammar_atom(production.clone()))]))) },
    sequence: { Rc::new(move |left_node, right_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_sequence_left_node_projection".to_string(), left_node.clone()), grammar_named_edge("grammar_sequence_right_node_projection".to_string(), right_node.clone())]))) },
    choice: { Rc::new(move |left_node, right_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_choice_left_node_projection".to_string(), left_node.clone()), grammar_named_edge("grammar_choice_right_node_projection".to_string(), right_node.clone())]))) },
    optional: { Rc::new(move |element_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_optional_element_node_projection".to_string(), element_node.clone())]))) },
    repeat: { Rc::new(move |element_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_repeat_element_node_projection".to_string(), element_node.clone())]))) },
    expect: { Rc::new(move |element_node, reason| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_expect_element_node_projection".to_string(), element_node.clone()), grammar_named_edge("grammar_expect_reason_node_projection".to_string(), grammar_atom(crate::v2_std_parse_refusal_reason::parse_refusal_reason_symbol(reason.clone())))]))) },
    refuse_on_match: { Rc::new(move |element_node, reason| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_refuse_on_match_element_node_projection".to_string(), element_node.clone()), grammar_named_edge("grammar_refuse_on_match_reason_node_projection".to_string(), grammar_atom(crate::v2_std_parse_refusal_reason::parse_refusal_reason_symbol(reason.clone())))]))) },
    after_line_break: { Rc::new(move |element_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_after_line_break_element_node_projection".to_string(), element_node.clone())]))) },
    not_predicate: { Rc::new(move |element_node| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_not_predicate_element_node_projection".to_string(), element_node.clone())]))) },
    infix_table: { Rc::new(move |operand_node, guard_node, operators| grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_infix_table_operand_node_projection".to_string(), operand_node.clone()), grammar_named_edge("grammar_infix_table_guard_node_projection".to_string(), guard_node.clone()), grammar_named_edge("grammar_infix_table_operators_node_projection".to_string(), grammar_infix_rows_node(operators.clone()))]))) },
    _phantom: std::marker::PhantomData,
}))
}

pub fn grammar_infix_associativity_symbol(associativity: InfixAssociativity) -> std::string::String {
    match associativity.clone() {
    InfixAssociativity::InfixLeft => "grammar_infix_left_associative".to_string(),
    InfixAssociativity::InfixNonAssociative => "grammar_infix_non_associative".to_string(),
}
}

pub fn grammar_infix_rows_node(rows: Rc<Vec<Rc<InfixOperatorRow>>>) -> Rc<Node> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        { let __fm = rows.clone(); if __fm.is_empty() { grammar_expr_node(Rc::new(vec![])) } else { let row = (*__fm)[0].clone(); let rest: Rc<Vec<_>> = Rc::new(__fm.skip(1)); grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_sequence_left_node_projection".to_string(), grammar_infix_row_node(row.clone())), grammar_named_edge("grammar_sequence_right_node_projection".to_string(), grammar_infix_rows_node(rest.clone()))])) } }
    })
}

pub fn grammar_infix_row_node(row: Rc<InfixOperatorRow>) -> Rc<Node> {
    grammar_expr_node(Rc::new(vec![grammar_named_edge("grammar_terminal_token_class_node_projection".to_string(), grammar_atom(row.token_class.clone())), grammar_named_edge("grammar_infix_binding_power_node_projection".to_string(), grammar_atom(v1_rt::symbol_intern_lexeme(crate::std_integer::int_to_decimal_string(row.binding_power.clone())))), grammar_named_edge("grammar_infix_associativity_node_projection".to_string(), grammar_atom(grammar_infix_associativity_symbol(row.associativity.clone())))]))
}

pub fn grammar_production_to_node(production: Rc<GrammarProduction>) -> Rc<Node> {
    Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}),
    children: Rc::new(vec![grammar_named_edge("grammar_production_name_node_projection".to_string(), grammar_atom(production.name.clone())), grammar_named_edge("grammar_production_expression_node_projection".to_string(), grammar_expr_to_node(production.expression.clone())), grammar_named_edge("grammar_production_emitted_node_projection".to_string(), production.emitted.clone())]),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}

pub fn grammar_production_to_list_step(acc: Rc<Vec<Rc<Edge>>>, production: Rc<GrammarProduction>) -> Rc<Vec<Rc<Edge>>> {
    crate::std_algebra::list_snoc_item(acc, grammar_named_edge(production.name.clone(), grammar_production_to_node(production.clone())))
}

pub fn grammar_productions_to_node(productions: Rc<Vec<Rc<GrammarProduction>>>) -> Rc<Node> {
    Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}),
    children: crate::std_algebra::fold_list(productions, Rc::new(vec![]), |acc, production| grammar_production_to_list_step(acc, production)),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}

pub fn grammar_root_to_node(root: Rc<GrammarRoot>) -> Rc<Node> {
    Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}),
    children: Rc::new(vec![grammar_named_edge("grammar_root_start_production_node_projection".to_string(), grammar_atom(root.start.clone())), grammar_named_edge("grammar_root_productions_node_projection".to_string(), grammar_productions_to_node(root.productions.clone()))]),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}

pub fn grammar_to_node(grammar: Rc<ParseGrammar>) -> Rc<Node> {
    match (*grammar.clone()).clone() {
    ParseGrammar::VoidGrammar => grammar_empty_node(),
    ParseGrammar::ModeledGrammar { root: root, .. } => grammar_root_to_node(root.clone()),
}
}

pub fn grammar_symbol_map_put(m: Rc<HashMap<Symbol, bool>>, sym: std::string::String) -> Rc<HashMap<Symbol, bool>> {
    v1_rt::rc_map_insert(m, sym, true)
}

pub fn grammar_symbol_list_put(m: Rc<HashMap<Symbol, bool>>, xs: Rc<Vec<Symbol>>) -> Rc<HashMap<Symbol, bool>> {
    crate::std_algebra::fold_list(xs, m, |acc, sym| grammar_symbol_map_put(acc, sym))
}

pub fn grammar_node_insert_atom_identities_child(m: Rc<HashMap<Symbol, bool>>, e: Rc<Edge>) -> Rc<HashMap<Symbol, bool>> {
    grammar_node_insert_atom_identities(m, e.target.clone())
}

pub fn grammar_node_insert_atom_identities(m: Rc<HashMap<Symbol, bool>>, n: Rc<Node>) -> Rc<HashMap<Symbol, bool>> {
    crate::std_algebra::fold_list(n.children.clone(), match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => grammar_symbol_map_put(m.clone(), id.clone()),
    Connective::Conj => m.clone(),
    Connective::Disj => m.clone(),
    Connective::Arrow => m.clone(),
    Connective::Instantiation => m.clone(),
} },
    NodeKind::ComputationNode { behavior: _, .. } => m.clone(),
}, |acc, e| grammar_node_insert_atom_identities_child(acc, e))
}

pub fn grammar_carried_symbol_map(grammar: Rc<ParseGrammar>) -> Rc<HashMap<Symbol, bool>> {
    grammar_node_insert_atom_identities(v1_rt::rc_empty_map::<_, _>(), grammar_to_node(grammar))
}

pub fn grammar_carries_symbol(grammar: Rc<ParseGrammar>, sym: std::string::String) -> bool {
    match v1_rt::lookup(&grammar_carried_symbol_map(grammar), sym) {
    Some(_) => true,
    std::option::Option::None => false,
}
}

